from dataclasses import dataclass

@dataclass
class ReadingItem:
    title: str
    available: bool = True

    def borrow(self):
        if not self.available:
            return False
        self.available = False
        return True

item = ReadingItem("Python Patterns")
print(item.borrow(), item.available)

from typing import Protocol

class Formatter(Protocol):
    def format(self, title: str) -> str: ...

class PlainFormatter:
    def format(self, title):
        return title.strip()

class Label: 
    def __init__(self, formatter: Formatter):
        self.formatter = formatter
    def render(self, title):
        return self.formatter.format(title)

print(Label(PlainFormatter()).render("  Python  "))

def parse_count(text: str) -> int | None:
    try:
        value = int(text.strip())
    except ValueError:
        return None
    return value if value >= 0 else None

for raw in (" 12 ", "-1", "many"):
    result = parse_count(raw)
    print(raw, result)

