class QuotaExceededError(Exception):
    pass

class Counter: 
    def __init__(self, limit): self.limit, self.value = limit, 0
    def __enter__(self): return self
    def __exit__(self, exc_type, exc, tb): return False
    def add(self):
        if self.value >= self.limit:
            raise QuotaExceededError("limit reached")
        self.value += 1

try:
    with Counter(1) as counter:
        counter.add(); counter.add()
except QuotaExceededError as error:
    print(type(error).__name__, str(error))

def clamp(value, low, high):
    if low > high:
        raise ValueError("low must not exceed high")
    return max(low, min(value, high))

checks = [clamp(0, 1, 3) == 1, clamp(4, 1, 3) == 3, clamp(2, 1, 3) == 2]
assert all(checks)
print("3 boundary checks passed")

from dataclasses import dataclass

@dataclass
class Note:
    text: str

class Notes:
    def __init__(self): self.items = []
    def add(self, text):
        text = text.strip()
        if not text: return False
        self.items.append(Note(text)); return True
    def search(self, phrase):
        phrase = phrase.strip().casefold()
        return [note.text for note in self.items if phrase and phrase in note.text.casefold()]

notes = Notes()
notes.add("Read about generators")
print(notes.search("GEN"))
